<template>
  <div
    v-layout-control="'run:Batch_Count'"
    v-tooltip.bottom="{ value: t('menu.batchCount'), showDelay: 600 }"
    class="batch-count h-10 w-10 overflow-hidden rounded-lg"
    :style="{ backgroundColor: 'var(--comfier-button-bg,var(--color-secondary-background))' }"
    :aria-label="t('menu.batchCount')"
  >
    <input
ref="batchCountInputRef" v-model="batchCountInput" type="text"
      inputmode="numeric" :aria-label="t('menu.batchCount')" :class="inputClass"
      @focus="onInputFocus" @input="onInput" @blur="onInputBlur"
      @keydown.enter.prevent="onInputEnter" />
  </div>
  <Button
v-layout-control="'run:Increment'" variant="secondary" size="unset"
    :aria-label="t('g.increment')" class="h-10 w-10 rounded-lg"
    :disabled="isIncrementDisabled" @click="incrementBatchCount">
    <TinyChevronIcon rotate-up />
  </Button>
  <Button
v-layout-control="'run:Decrement'" variant="secondary" size="unset"
    :aria-label="t('g.decrement')" class="h-10 w-10 rounded-lg"
    :disabled="isDecrementDisabled" @click="decrementBatchCount">
    <TinyChevronIcon />
  </Button>
</template>

<script lang="ts" setup>
import { vLayoutControl } from '@/comfier/layoutControl'

import { storeToRefs } from 'pinia'
import { computed, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'

import Button from '@/components/ui/button/Button.vue'
import { useSettingStore } from '@/platform/settings/settingStore'
import { useQueueSettingsStore } from '@/stores/queueSettingsStore'

import TinyChevronIcon from './TinyChevronIcon.vue'

const { t } = useI18n()

const queueSettingsStore = useQueueSettingsStore()
const { batchCount } = storeToRefs(queueSettingsStore)

const settingStore = useSettingStore()
const minQueueCount = 1
const maxQueueCount = computed(() =>
  settingStore.get('Comfy.QueueButton.BatchCountLimit')
)

const batchCountInputRef = ref<HTMLInputElement | null>(null)
const batchCountInput = ref(String(batchCount.value))
const isEditing = ref(false)

const isIncrementDisabled = computed(
  () => batchCount.value >= maxQueueCount.value
)
const isDecrementDisabled = computed(() => batchCount.value <= minQueueCount)
const inputClass =
  'h-full w-full min-w-0 border-none bg-transparent pl-1 pr-0 text-center text-sm font-normal tabular-nums text-base-foreground outline-none'

watch(batchCount, (nextBatchCount) => {
  if (!isEditing.value) {
    batchCountInput.value = String(nextBatchCount)
  }
})

const clampBatchCount = (nextBatchCount: number): number =>
  Math.min(Math.max(nextBatchCount, minQueueCount), maxQueueCount.value)

const setBatchCount = (nextBatchCount: number) => {
  batchCount.value = clampBatchCount(nextBatchCount)
  batchCountInput.value = String(batchCount.value)
}

const incrementBatchCount = () => {
  setBatchCount(batchCount.value + 1)
}

const decrementBatchCount = () => {
  setBatchCount(batchCount.value - 1)
}

const onInputFocus = () => {
  isEditing.value = true
}

const onInput = (event: Event) => {
  const input = event.target as HTMLInputElement
  batchCountInput.value = input.value.replace(/[^0-9]/g, '')
}

const onInputBlur = () => {
  isEditing.value = false
  const parsedInput = Number.parseInt(batchCountInput.value, 10)
  setBatchCount(Number.isNaN(parsedInput) ? minQueueCount : parsedInput)
}

const onInputEnter = () => {
  batchCountInputRef.value?.blur()
}
</script>
